using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.UI;using Blacksmith;using Object=UnityEngine.Object;
public static class ReleaseMonsterQA{
 static string Output=>SessionState.GetString("PoorSmithReleaseQA.Output",null)??throw new InvalidOperationException("Set owned isolated output directory first.");
 static int step;static double next,deadline,phaseEnd;static PlayerAssimilate player;static StoneGolemController golem;static VampireBatController bat;static MossSlimeController slime;static StoneGolemRockProjectile rock;static List<string> checks=new(),errors=new(),states=new();static List<float> damage=new();static float hp;static Vector2 home;static int coreBefore;static bool flightOverlap;static object Get(object o,string n)=>o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public)?.GetValue(o);static string State(object o){var m=Get(o,"stateMachine");return m?.GetType().GetProperty("Current")?.GetValue(m)?.GetType().Name??"none";}static void SetState(object o,string name)=>o.GetType().GetMethod("ChangeState",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,new[]{Get(o,name)});
 static void Check(bool b,string s){if(!b)throw new Exception(s);checks.Add(s);Debug.Log("RELEASE_MONSTER_PASS "+s);}
 public static void Run(){if(!Directory.Exists(Output))throw new InvalidOperationException("Create owned output first");if(PlayerSettings.companyName!="BatterMapValidation")throw new Exception("isolation");SessionState.SetBool("ReleaseMonsterQA",true);EditorSceneManager.OpenScene(TitleSceneController.ScenePath);EditorApplication.isPlaying=true;}
 [InitializeOnLoadMethod]static void Resume(){if(!SessionState.GetBool("ReleaseMonsterQA",false))return;Application.runInBackground=true;EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();next=EditorApplication.timeSinceStartup+2;deadline=next+180;EditorApplication.update+=Tick;Application.logMessageReceived+=Log;}
 static void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception)errors.Add(m+"\n"+s);}
 static void Tool(ToolType type){var t=player.GetComponent<PlayerToolController>();for(int i=0;i<t.ToolSlotCount;i++)if(t.GetToolAtSlot(i)?.ToolType==type){t.SelectToolSlot(i);return;}throw new Exception("missing playable tool "+type);}
 static int Core(){var loop=SmithingLoop.Instance;var item=loop.FieldItemFor(new Blacksmith.Stack("golem_core",1));return Object.FindObjectsByType<ItemDropInteractable>(FindObjectsSortMode.None).Where(x=>x.ItemData==item).Sum(x=>x.Amount)+player.GetComponent<InventorySystem>().GetItemCount(item);}
 static void Tick(){EditorApplication.QueuePlayerLoopUpdate();if(!EditorApplication.isPlaying||EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+.06;try{if(EditorApplication.timeSinceStartup>deadline)throw new Exception("timeout step="+step+" states="+string.Join(",",states));if(golem!=null){string st=State(golem);if(states.Count==0||states.Last()!=st)states.Add(st);}switch(step){
 case 0:var title=Object.FindFirstObjectByType<TitleSceneController>();if(title==null)return;((Button)Get(title,"continueButton")).onClick.Invoke();step=1;break;
 case 1:if(Object.FindFirstObjectByType<FieldSceneState>()?.Ready!=true){if(CampaignController.Instance?.Ready==true&&!FieldSceneTravel.Busy)FieldSceneTravel.BeginToField();return;}golem=Object.FindFirstObjectByType<StoneGolemController>();if(golem==null){if(phaseEnd==0)phaseEnd=EditorApplication.timeSinceStartup+8;if(EditorApplication.timeSinceStartup<phaseEnd)return;}player=Object.FindFirstObjectByType<PlayerAssimilate>();player.Damaged+=d=>damage.Add(d);var loop=SmithingLoop.Instance;var inv=new InventoryService(loop.SmithData,loop.Catalog);InventoryService.Add(inv.Data.chest,new Blacksmith.Stack("wood_sword",1));inv.Equip(inv.Data.chest.Last(x=>x.itemId=="wood_sword"));if(!inv.Data.equipment.Any(e=>e.slot=="Pickaxe")){InventoryService.Add(inv.Data.chest,new Blacksmith.Stack("town_pick_1",1));inv.Equip(inv.Data.chest.Last(x=>x.itemId=="town_pick_1"));}loop.RefreshEquipment();golem=Object.FindFirstObjectByType<StoneGolemController>();Check(golem!=null&&Object.FindObjectsByType<StoneGolemController>(FindObjectsSortMode.None).Length==1,"actual field spawns exactly one golem");foreach(var x in Object.FindObjectsByType<VampireBatController>(FindObjectsSortMode.None))x.enabled=false;foreach(var x in Object.FindObjectsByType<MossSlimeController>(FindObjectsSortMode.None))x.enabled=false;home=golem.transform.position;Check(FieldSceneTravel.BeginFieldWarp(home+Vector2.right*2.2f+Vector2.up*2),"golem authored corridor arrival");step=2;next+=2;break;
 case 2:if(FieldSceneTravel.Busy)return;player.RestoreRemainingHealth(player.MaxAssimilation);damage.Clear();hp=golem.CurrentHealth;Tool(ToolType.Sword);golem.Interact(player.GetComponent<PlayerInteraction>());golem.TakeDamage(5);Check(golem.CurrentHealth==hp,"golem ordinary weapon/direct generic damage ignored");step=3;next+=2;break;
 case 3:Check(State(golem)=="DormantState","golem dormant has no first-strike attack");Tool(ToolType.Pickaxe);golem.Interact(player.GetComponent<PlayerInteraction>());Check(Mathf.Abs(golem.CurrentHealth-(hp-13))<.01f&&State(golem)=="AwakingState","actual pickaxe13 damage and awakening");step=4;phaseEnd=EditorApplication.timeSinceStartup+18;break;
 case 4:if(!damage.Any(d=>Mathf.Abs(d-25)<.1f)){if(EditorApplication.timeSinceStartup>phaseEnd)throw new Exception("natural golem slam not observed "+State(golem));return;}Check(true,"actual awakened AI walks/slams and deals25");golem.enabled=false;player.RestoreRemainingHealth(player.MaxAssimilation);damage.Clear();Check(FieldSceneTravel.BeginFieldWarp((Vector2)golem.transform.position+Vector2.right*5+Vector2.up*2),"ranged attack prepared target arrival");step=5;next+=2;break;
 case 5:if(FieldSceneTravel.Busy)return;player.RestoreRemainingHealth(player.MaxAssimilation);damage.Clear();golem.enabled=true;SetState(golem,"throwState");step=6;phaseEnd=EditorApplication.timeSinceStartup+8;break;
 case 6:rock=Object.FindFirstObjectByType<StoneGolemRockProjectile>();if(rock==null){if(EditorApplication.timeSinceStartup>phaseEnd)throw new Exception("rock release not observed");return;}golem.enabled=false;var rb=player.GetComponent<Rigidbody2D>();rb.position=rock.transform.position;rb.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();Check(damage.Count==0,"rock flying overlap gives no immediate contact damage");step=7;next+=.08;break;
 case 7:if(rock==null)throw new Exception("rock landed before controlled landing sample");Check(damage.Count==0,"flight overlap still no damage on next frame");var dest=(Vector2)Get(rock,"destination");var body=player.GetComponent<Collider2D>();var r=player.GetComponent<Rigidbody2D>();r.position=new Vector2(dest.x,dest.y+player.transform.position.y-body.bounds.min.y+.02f);r.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();player.GetComponent<PlayerMovement>().ResetAfterTeleport();step=8;next+=1;break;
 case 8:Check(damage.Count(d=>Mathf.Abs(d-20)<.1f)==1&&damage.Count==1&&Object.FindFirstObjectByType<StoneGolemRockProjectile>()==null,"rock landing deals20 exactly once and cleans up");player.RestoreRemainingHealth(player.MaxAssimilation);hp=golem.CurrentHealth;golem.enabled=true;Check(FieldSceneTravel.BeginFieldWarp(home+Vector2.left*25+Vector2.up*2),"far player position for return");step=89;next+=1;break;
 case 89:if(FieldSceneTravel.Busy)return;player.GetComponent<Rigidbody2D>().position=home+Vector2.left*25;player.GetComponent<Rigidbody2D>().linearVelocity=Vector2.zero;player.GetComponent<Rigidbody2D>().simulated=false;Physics2D.SyncTransforms();Check(Vector2.Distance(player.transform.position,golem.transform.position)>12,"prepared stationary player beyond authored return distance");SetState(golem,"fiveStepState");step=9;phaseEnd=EditorApplication.timeSinceStartup+18;break;
 case 9:if(State(golem)!="DormantState"){if(EditorApplication.timeSinceStartup>phaseEnd)throw new Exception("return home timeout "+State(golem)+" distance="+Vector2.Distance(player.transform.position,golem.transform.position)+" player="+player.transform.position+" golem="+golem.transform.position+" scale="+Time.timeScale);return;}Check(Vector2.Distance(golem.transform.position,home)<.35f&&golem.CurrentHealth==hp,"golem returns to authored home without healing");
 player.GetComponent<Rigidbody2D>().simulated=false;player.transform.position=golem.transform.position+Vector3.right*10;player.GetComponent<Rigidbody2D>().position=player.transform.position;Physics2D.SyncTransforms();SetState(golem,"fiveStepState");var cycle=Get(golem,"fiveStepState");var finishField=cycle.GetType().GetField("finish",BindingFlags.Instance|BindingFlags.NonPublic);finishField.SetValue(cycle,Time.time-1);((IBehaviourState)cycle).Tick();float expiry=(float)finishField.GetValue(cycle);File.WriteAllText(Output+"/golem-cycle.json",JsonUtility.ToJson(new CycleReport{prepared=true,restarted=expiry>Time.time,expiry=expiry,clock=Time.time,distance=Vector2.Distance(player.transform.position,golem.transform.position)},true));Check(expiry>Time.time,"golem intermediate-distance walk cycle restarts without same-state deadlock");SetState(golem,"dormantState");player.GetComponent<Rigidbody2D>().simulated=true;coreBefore=Core();Tool(ToolType.Pickaxe);for(int k=0;k<Mathf.CeilToInt(golem.MaxHealth/13)+2&&!golem.IsDead;k++)golem.Interact(player.GetComponent<PlayerInteraction>());Check(golem.IsDead,"pickaxe lethal damage reaches dead state hp="+golem.CurrentHealth+" tool="+player.GetComponent<PlayerInteraction>().CurrentTool?.ToolType);golem.Interact(player.GetComponent<PlayerInteraction>());step=10;next+=3;break;
 case 10:Check(Core()==coreBefore+1,"golem repeated lethal interaction creates one core only");bat=Object.FindObjectsByType<VampireBatController>(FindObjectsSortMode.None).First();bat.enabled=true;Check(FieldSceneTravel.BeginFieldWarp((Vector2)bat.transform.position+Vector2.down*2),"actual bat zone arrival");step=11;next+=2;break;
 case 11:if(FieldSceneTravel.Busy)return;player.transform.position=bat.transform.position+Vector3.down*2;player.GetComponent<Rigidbody2D>().position=player.transform.position;player.GetComponent<Rigidbody2D>().gravityScale=0;player.GetComponent<Rigidbody2D>().linearVelocity=Vector2.zero;Physics2D.SyncTransforms();player.RestoreRemainingHealth(player.MaxAssimilation);damage.Clear();step=12;phaseEnd=EditorApplication.timeSinceStartup+14;break;
 case 12:if(damage.Count==0){if(EditorApplication.timeSinceStartup>phaseEnd)throw new Exception("bat natural attack not observed state="+State(bat));return;}Check(true,"bat actual AI attack damages player");bat.TakeDamage(bat.MaxHealth*2);bat.TakeDamage(bat.MaxHealth*2);Check(bat.IsDead,"bat lethal/repeated damage reaches dead state");slime=Object.FindObjectsByType<MossSlimeController>(FindObjectsSortMode.None).First();slime.enabled=true;Check(FieldSceneTravel.BeginFieldWarp((Vector2)slime.transform.position+Vector2.right*1.1f+Vector2.up*2),"actual slime zone arrival");step=13;next+=2;break;
 case 13:if(FieldSceneTravel.Busy)return;player.transform.position=slime.transform.position+Vector3.right*1.1f;player.GetComponent<Rigidbody2D>().position=player.transform.position;player.GetComponent<Rigidbody2D>().linearVelocity=Vector2.zero;Physics2D.SyncTransforms();player.RestoreRemainingHealth(player.MaxAssimilation);damage.Clear();step=14;phaseEnd=EditorApplication.timeSinceStartup+12;break;
 case 14:if(damage.Count==0){if(EditorApplication.timeSinceStartup>phaseEnd)throw new Exception("slime actual damage not observed state="+State(slime));return;}Check(true,"slime actual AI/contact damages player");slime.TakeDamage(slime.MaxHealth*2);slime.TakeDamage(slime.MaxHealth*2);Check(slime.IsDead,"slime lethal/repeated damage reaches dead state");Finish(true,"Authored field, prepared warps/tools/health and isolated monster encounters. Golem ranged state selected explicitly; natural five-step ranged decision/native combat not claimed.");break;
 }}catch(Exception ex){Finish(false,ex.ToString());}}
 static void Finish(bool ok,string msg){SessionState.SetBool("ReleaseMonsterQA",false);EditorApplication.update-=Tick;Application.logMessageReceived-=Log;File.WriteAllText(Output+"/monsters.json",JsonUtility.ToJson(new Report{passed=ok&&errors.Count==0,message=msg,checks=checks.ToArray(),errors=errors.ToArray(),states=states.ToArray()},true));EditorApplication.isPlaying=false;}
 [Serializable]class CycleReport{public bool prepared,restarted;public float expiry,clock,distance;}
 [Serializable]class Report{public bool passed;public string message;public string[] checks,errors,states;}
}
